import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const u=JSON.parse('{"title":"38、【睽】 兌下離上","description":"周易口訣義 - 38、【睽】 兌下離上","frontmatter":{"title":"38、【睽】 兌下離上","description":"周易口訣義 - 38、【睽】 兌下離上"},"headers":[],"relativePath":"classics/koujueyi/040.md","filePath":"classics/koujueyi/040.md"}'),r={name:"classics/koujueyi/040.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_38、【睽】-兌下離上" tabindex="-1">38、【睽】 兌下離上 <a class="header-anchor" href="#_38、【睽】-兌下離上" aria-label="Permalink to “38、【睽】 兌下離上”">​</a></h1><p>彖曰：睽，火動而上，澤動而下，二女同居，其志不同行。說而麗乎明，柔進而上行，得中而應乎剛，是以「小事吉」。天地「睽」而其事同也，男女「睽」而其志通也，萬物「睽」而其事類也，「睽」之時用大矣哉！</p><p>象曰：上火下澤，「睽」。君子以同而異。</p><p>初九：悔亡。喪馬勿逐，自復。見惡人，無咎。</p><p>象曰：「見惡人」，以避咎也。</p><p>九二：遇主於巷，無咎。</p><p>象曰：「遇主於巷」，未失道也。</p><p>六三：見輿曳，其牛掣，其人天且劓，無初有終。</p><p>象曰：「見輿曳」，位不當也。「無初有終」，遇剛也。</p><p>九四：睽孤，遇元夫，交孚，厲，無咎。</p><p>象曰：「交孚無咎」，志行也。</p><p>六五：悔亡。厥宗噬膚，往何咎。</p><p>象曰：「厥宗噬膚」，往有慶也。</p><p>上九：睽孤，見豕負塗，載鬼一車，先張之弧，後說之弧，匪寇婚媾，往遇雨則吉。</p><p>象曰：「遇雨」之「吉」，群疑亡也。</p><p>無（四庫全書標明，摘錄時缺豫、隨、無妄、大壯、晉、睽、蹇、解、中孚八卦）</p>',16)])])}const m=e(r,[["render",i]]);export{u as __pageData,m as default};
